css:
/* ===== 晋江段评 · 默认模板 ===== */
.be-card.be-custom {
  position: relative;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 100%;
  background: #ffffff;
  color: #2b2b2b;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Segoe UI", sans-serif;
  border-radius: 12px;
  border: 1px solid #e8ece9;
  box-shadow: 0 2px 14px rgba(31, 61, 46, 0.06);
  padding: 18px 20px 16px;
  overflow: hidden;
}
.be-card.be-custom::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #2f9e63, #8fd0a9);
}
.be-card.be-custom .be-head,
.be-card.be-custom .be-meta,
.be-card.be-custom .be-source {
  display: flex;
  align-items: center;
}
.be-card.be-custom .be-source {
  gap: 10px;
  margin-bottom: 4px;
}
.be-card.be-custom .be-char-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #eaf3ee;
  border: 2px solid #2f9e63;
  flex-shrink: 0;
}
.be-card.be-custom .be-avatar { display: none; }
.be-card.be-custom .be-source .author {
  font-size: 16px;
  font-weight: 700;
  color: #1f3d2e;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.be-card.be-custom .be-source .title {
  font-size: 12px;
  color: #2f9e63;
  background: #e9f6ee;
  padding: 2px 10px;
  border-radius: 20px;
  white-space: nowrap;
}
.be-card.be-custom .be-source .chapter {
  font-size: 12px;
  color: #9aa8a0;
  white-space: nowrap;
}
.be-card.be-custom .be-name {
  display: block;
  font-size: 11px;
  color: #b0b8b3;
  margin: -2px 0 10px 54px;
}
.be-card.be-custom .be-quote {
  font-size: var(--be-quote-size, 15px);
  line-height: var(--be-quote-lh, 1.6);
  color: #4a4a4a;
  background: #f7faf8;
  border-left: 2px solid #2f9e63;
  border-radius: 0 8px 8px 0;
  padding: 10px 12px;
  margin: 4px 0 12px;
}
.be-card.be-custom .be-quote p { text-indent: 0; margin: 0 0 0.4em; }
.be-card.be-custom .be-quote-orig {
  font-size: 12px;
  color: #b6bdb9;
  margin-top: 10px;
}
.be-card.be-custom .be-date { display: none; }
.be-card.be-custom .be-date-cn {
  font-size: 11px;
  color: #c6cdc9;
  margin-top: 4px;
}
.be-card.be-custom .be-watermark {
  text-align: right;
  font-size: 10px;
  color: #d4e6dc;
  letter-spacing: 1px;
  margin-top: 4px;
}

comments:
/* ===== 晋江段评 · 评述模块（分割线分隔，与卡片一体） ===== */
.be-comments {
  background: #ffffff;
  border-top: 1px solid #ecece8;
  /* 评论渲染在卡片内部，通栏贴边（抵消卡片 padding 18px 20px 16px），与卡片共用边框圆角阴影 */
  margin: 0 -20px -16px !important;
}
.be-comment {
  display: flex;
  gap: 10px;
  padding: 12px 20px;
  border-bottom: 1px solid #f2f2ee;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #ecece6;
  flex-shrink: 0;
  margin-top: 2px;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 7px; }
.be-comment-name { font-size: 12.5px; color: #3b7bd1; font-weight: 700; }
.be-comment-id { font-size: 11px; color: #9d9d94; }
.be-comment-time { font-size: 11px; color: #c0c0b6; }
.be-comment-text { font-size: 13px; color: #33332e; line-height: 1.65; margin-top: 3px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #b35b2e; }
